<?php session_start();if(!isset($_SESSION["adminsid"])){header("Location: ../index.php?msg=Please+log+in+as+Admin");exit;}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$c=$db->getConnection();$isbn=trim($_POST['ISBN']??'');$name=trim($_POST['bookName']??'');$author=trim($_POST['authorName']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);if($isbn===''||$name===''||$author===''||$price===false||$qty===false||$price<0||$qty<0){header("Location: admin_service_dashboard.php?msg=Invalid+book+details");exit;}$s=$c->prepare("INSERT INTO books(ISBN,bookName,authorName,price,quantity) VALUES(?,?,?,?,?)");$s->bind_param("sssii",$isbn,$name,$author,$price,$qty);$ok=$s->execute();$s->close();$db->closeConnection();header("Location: admin_service_dashboard.php?msg=".($ok?"Book+added+successfully":"Unable+to+add+book"));exit;?>